function parseUiNumber(value){try{return Number(C.numberText(value))||0}catch{return NaN}}
function majorToBaseUi(value,unit){try{return C.quantityBase(value,unit)}catch{return 0}}
function baseToMajorCost(unitCost,unit){if(unitCost===null||unitCost===undefined||!Number.isFinite(Number(unitCost)))return null;return Number(unitCost)*(unit==='count'?1:1000)}
function costTextPerMajor(unitCost,unit){const v=baseToMajorCost(unitCost,unit);return v===null?'نامشخص':`${money(Math.round(v))} / ${majorUnitLabel(unit)}`}
function purchaseUnitOperationContext(itemId,purchaseUnitId,unitCount,actualMajor){const item=inventoryItemById(itemId);if(!item)return{item:null,unit:null,unitCount:0,quantityBase:0,summary:'',warning:''};const count=parseUiNumber(unitCount),unit=purchaseUnitsForItem(itemId,true).find(u=>Number(u.id)===Number(purchaseUnitId||0))||null;let quantityBase=0;if(!unit)quantityBase=majorToBaseUi(unitCount,item.base_unit);else if(unit.conversion_mode==='actual_quantity'||unit.review_status==='needs_review')quantityBase=majorToBaseUi(actualMajor,item.base_unit);else quantityBase=Math.round(count*Number(unit.base_quantity||0));let summary='';if(unit&&count>0){if((unit.conversion_mode==='actual_quantity'||unit.review_status==='needs_review')&&quantityBase>0)summary=`${L.number(count)} ${unit.name} · مقدار واقعی کل: ${majorText(quantityBase,item.base_unit)} ${majorUnitLabel(item.base_unit)}`;else if(unit.conversion_mode==='fixed'&&Number(unit.base_quantity)>0)summary=`${L.number(count)} ${unit.name} × ${majorText(Number(unit.base_quantity),item.base_unit)} ${majorUnitLabel(item.base_unit)} = ${majorText(quantityBase,item.base_unit)} ${majorUnitLabel(item.base_unit)}`;}const warning=unit?.review_status==='needs_review'?'تبدیل این واحد خرید هنوز نیازمند بازبینی است؛ مقدار واقعی همین عملیات مبنای ثبت می‌شود.':'';return{item,unit,unitCount:count,quantityBase,summary,warning}}
